<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CV Bank</title><style>body{margin:0;background:#0f1016;color:#eef0f6;font:15px system-ui}.top{height:58px;border-bottom:1px solid #292c38;display:flex;align-items:center;gap:12px;padding:0 5%;color:#9da5b7}.top strong{color:#fff;font-size:18px}.top a{margin-left:auto;color:#a89cff;text-decoration:none}.shell{max-width:1180px;margin:auto;padding:44px 28px 80px}.eyebrow{color:#8d7cff;letter-spacing:1.8px;font-size:11px;font-weight:800}h1{font-size:34px;margin:0 0 8px}h2{margin-top:34px}.muted{color:#9ca3b5}.card{background:#181a23;border:1px solid #303342;border-radius:14px;padding:22px;margin-top:18px}form{display:grid;grid-template-columns:1fr 1fr;gap:12px}input,textarea,select{background:#111218;color:#fff;border:1px solid #3b3e4d;border-radius:8px;padding:11px}textarea{grid-column:1/-1;min-height:70px}button{background:#4f46e5;color:white;border:0;border-radius:8px;padding:11px 16px;font-weight:600;cursor:pointer}.wide{grid-column:1/-1}.success{background:#123b2b;border:1px solid #27744e;padding:12px;border-radius:8px}.row{display:flex;justify-content:space-between;gap:16px;align-items:center;border-top:1px solid #2a2d38;padding:15px 0}.row:first-child{border-top:0}.pill{padding:4px 9px;border-radius:99px;background:#292d42;color:#b8c0ff;font-size:12px}@media(max-width:700px){body{padding:22px}form{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><header class="top"><strong>Judibas</strong><span>›</span><span>Products</span><span>›</span><span>CV Bank</span><a href="/products">All products ?</a></header><main class="shell"><p class="eyebrow">JUDIBAS / HUMAN RESOURCES</p><h1>CV Bank</h1><p class="muted">Publish opportunities and review private candidate applications.</p>@if(session('success'))<p class="success">{{session('success')}}</p>@endif<div class="card"><h2>Publish a job</h2><form method="post" action="/cv-bank/jobs">@csrf<input name="title" placeholder="Job title" required><input name="department" placeholder="Department" required><textarea name="description" placeholder="Short description"></textarea><button class="wide">Save job</button></form></div><div class="card"><h2>Open jobs</h2>@forelse($jobs as $job)<div class="row"><div><strong>{{$job->title}}</strong><div class="muted">{{$job->department}} Â· {{$job->active?'Active':'Archived'}}</div></div>@if($job->active)<form method="post" action="/cv-bank/jobs/{{$job->id}}">@csrf @method('DELETE')<button>Archive</button></form>@endif</div>@empty<p class="muted">No jobs published. General applications are still available.</p>@endforelse</div><div class="card"><h2>Applications</h2>@forelse($applications as $a)<div class="row"><div><strong>{{$a->name}}</strong><div class="muted">{{$a->department}} Â· {{$a->job_title ?: 'General application'}} Â· {{$a->email}}</div></div><div><span class="pill">{{$a->status}}</span> <a href="/cv-bank/applications/{{$a->id}}/cv" style="color:#a5b4fc">Download CV</a></div></div><form method="post" action="/cv-bank/applications/{{$a->id}}" style="display:flex;margin-bottom:10px">@csrf @method('PATCH')<select name="status"><option>new</option><option>reviewing</option><option>shortlisted</option><option>rejected</option><option>hired</option></select><input name="notes" placeholder="Internal note"><button>Update</button></form>@empty<p class="muted">No applications yet.</p>@endforelse</div></main></body></html>
